import numpy as np, pandas as pd
from lmfit.models import LorentzianModel, LinearModel
for k in 'ABD':
    d=pd.read_csv(f'spectrum_{k}.csv'); x=d.shift_cm1.values;y=d.intensity.values
    s=(x>390)&(x<422)
    res={}
    for n in (1,2):
        mod=LinearModel(prefix='b_')
        for i in range(n): mod+=LorentzianModel(prefix=f'p{i}_')
        p=mod.make_params(b_slope=0,b_intercept=y[s].min())
        for i in range(n):
            c=[404,407][i]; p[f'p{i}_center'].set(c,min=396,max=414);p[f'p{i}_sigma'].set(2,min=1.2,max=6);p[f'p{i}_amplitude'].set(np.ptp(y[s])*3,min=0)
        r=mod.fit(y[s],p,x=x[s]);res[n]=r
        print(k,n,'chi2red %.2f BIC %.1f'%(r.redchi,r.bic),[(round(r.params[f'p{i}_center'].value,2),round(2*r.params[f'p{i}_sigma'].value,2)) for i in range(n)])
